import React, { useState } from 'react';
import './Upload.css';

function Upload({ allerVers, utilisateur }) {
  const [titre, setTitre] = useState('');
  const [genre, setGenre] = useState('');
  const [type, setType] = useState('single');
  const [pochette, setPochette] = useState(null);
  const [fichierSingle, setFichierSingle] = useState(null);
  const [pistes, setPistes] = useState([{ titre: '', fichier: null }]);
  const [message, setMessage] = useState('');
  const [chargement, setChargement] = useState(false);

  const ajouterPiste = () => {
    if (pistes.length < 15) {
      setPistes([...pistes, { titre: '', fichier: null }]);
    }
  };

  const supprimerPiste = (index) => {
    const nouvellesPistes = pistes.filter((_, i) => i !== index);
    setPistes(nouvellesPistes);
  };

  const modifierPiste = (index, champ, valeur) => {
    const nouvellesPistes = [...pistes];
    nouvellesPistes[index][champ] = valeur;
    setPistes(nouvellesPistes);
  };

  const handleUpload = async () => {
    setChargement(true);
    setMessage('');

    try {
      const formData = new FormData();
      formData.append('titre', titre);
      formData.append('genre', genre);
      formData.append('type', type);
      formData.append('artiste_id', utilisateur.id);

      if (pochette) formData.append('pochette', pochette);

      if (type === 'single') {
        if (fichierSingle) formData.append('fichier', fichierSingle);
      } else {
        pistes.forEach((piste, index) => {
          if (piste.fichier) {
            formData.append(`piste_fichier_${index}`, piste.fichier);
            formData.append(`piste_titre_${index}`, piste.titre);
          }
        });
        formData.append('nombre_pistes', pistes.length);
      }

      const reponse = await fetch('/api/musiques/upload', {
        method: 'POST',
        body: formData
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        setMessage('✅ ' + donnees.message);
        setTimeout(() => allerVers('accueil'), 3000);
      } else {
        setMessage('❌ ' + donnees.message);
      }

    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }

    setChargement(false);
  };

  return (
    <div className="upload-page">
      <div className="upload-box">
        <h1 className="upload-logo">🎵 Varim Music</h1>
        <h2 className="upload-titre">Publier ma musique</h2>

        {message && <div className="upload-message">{message}</div>}

        <div className="upload-champ">
          <label>Titre</label>
          <input
            type="text"
            placeholder="Titre de votre musique"
            value={titre}
            onChange={(e) => setTitre(e.target.value)}
          />
        </div>

        <div className="upload-champ">
          <label>Genre</label>
          <select value={genre} onChange={(e) => setGenre(e.target.value)}>
            <option value="">Choisir un genre</option>
            <option value="Afrobeat">Afrobeat</option>
            <option value="Coupé-Décalé">Coupé-Décalé</option>
            <option value="Ndombolo">Ndombolo</option>
            <option value="Afropop">Afropop</option>
            <option value="Hip-Hop Africain">Hip-Hop Africain</option>
            <option value="Gospel">Gospel</option>
            <option value="Zouk">Zouk</option>
            <option value="Bikutsi">Bikutsi</option>
            <option value="Rumba Congolaise">Rumba Congolaise</option>
            <option value="Autre">Autre</option>
          </select>
        </div>

        <div className="upload-champ">
          <label>Type</label>
          <div className="upload-roles">
            <div
              className={`role-carte ${type === 'single' ? 'active' : ''}`}
              onClick={() => setType('single')}
            >
              🎵 Single — 500 FCFA
            </div>
            <div
              className={`role-carte ${type === 'album' ? 'active' : ''}`}
              onClick={() => setType('album')}
            >
              💿 Album — 5000 FCFA
            </div>
          </div>
        </div>

        <div className="upload-champ">
          <label>Pochette (image)</label>
          <input
            type="file"
            accept="image/*"
            onChange={(e) => setPochette(e.target.files[0])}
          />
        </div>

        {type === 'single' && (
          <div className="upload-champ">
            <label>Fichier MP3</label>
            <input
              type="file"
              accept="audio/mp3,audio/*"
              onChange={(e) => setFichierSingle(e.target.files[0])}
            />
          </div>
        )}

        {type === 'album' && (
          <div className="upload-pistes">
            <h3>🎵 Pistes de l'album ({pistes.length}/15)</h3>
            {pistes.map((piste, index) => (
              <div key={index} className="piste-item">
                <span className="piste-numero">#{index + 1}</span>
                <input
                  type="text"
                  placeholder={`Titre piste ${index + 1}`}
                  value={piste.titre}
                  onChange={(e) => modifierPiste(index, 'titre', e.target.value)}
                />
                <input
                  type="file"
                  accept="audio/mp3,audio/*"
                  onChange={(e) => modifierPiste(index, 'fichier', e.target.files[0])}
                />
                {pistes.length > 1 && (
                  <button
                    className="btn-supprimer"
                    onClick={() => supprimerPiste(index)}
                  >
                    ✕
                  </button>
                )}
              </div>
            ))}
            {pistes.length < 15 && (
              <button className="btn-ajouter-piste" onClick={ajouterPiste}>
                + Ajouter une piste
              </button>
            )}
          </div>
        )}

        <button
          className="upload-btn"
          onClick={handleUpload}
          disabled={chargement}
        >
          {chargement ? 'Publication en cours...' : 'Publier ma musique'}
        </button>

        <p className="upload-lien">
          <a href="#" onClick={() => allerVers('accueil')}>← Retour à l'accueil</a>
        </p>
      </div>
    </div>
  );
}

export default Upload;
